#!/usr/bin/env bash
# check: The perches' ink is what the served words make
# src/birds/inkbirds/255-perch-ink.js (where a bird can stand on the words) is generated by tools/birds/perch/make.mjs
# from the lettered name in site/index.html and the served fonts, in Chrome; made again here, it must match.
# plant: {"file": "src/birds/inkbirds/255-perch-ink.js", "find": "room: 34", "with": "room: 35", "why": "a perch table edited by hand"}
if [ -z "${PW_CORE:-}" ] && ! node -e "require.resolve('playwright')" 2>/dev/null; then
  npm install --no-save --no-audit --no-fund --prefix "$RUNNER_TEMP/pw" playwright-core@1.49.1 > /dev/null
  export PW_CORE="$RUNNER_TEMP/pw/node_modules/playwright-core"
fi
node tools/birds/perch/make.mjs --check
